//! Disposable microbenchmark of the existing captureWord:of: operation.
#[path = "../tests/support/oop.rs"]
mod oop;
use birnam_abi::size;
unsafe extern "C" { fn clock_gettime_nsec_np(clock: u32) -> u64; }
fn main() {
    let host = oop::bootstrap();
    let q = host.scope();
    let source = q.string(b"[[:captured | [| captured]] value: 41]").unwrap();
    let block = q.call(host.named(b"Codegen").unwrap(), b"eval:", &[source]).unwrap();
    q.check_result(block).unwrap();
    let expected = q.call(block, b"value", &[]).unwrap();
    let word = q.call(host.named(b"Integer").unwrap(), b"wordOf:", &[expected]).unwrap();
    assert_eq!(q.word_bits(word).unwrap(), 41);
    let selector = q.keep(host.intern(b"captureWord:of:").unwrap()).unwrap();
    let index = [size(0).unwrap(), block];
    let receiver = host.named(b"Block").unwrap();
    let read = || unsafe { host.id.send(receiver, selector, &index).unwrap() };
    for _ in 0..10000 { assert_eq!(read(), expected); }
    for _ in 0..7 {
        let start = unsafe { clock_gettime_nsec_np(16) };
        for _ in 0..1000000 { assert_eq!(read(), expected); }
        println!("{}", unsafe { clock_gettime_nsec_np(16) } - start);
    }
}
